# represent poly as coeffs up to degree 4

def mul(a,b):
    tmp=[0]*(len(a)+len(b)-1)
    for i,x in enumerate(a):
        for j,y in enumerate(b):
            tmp[i+j]+=x*y
    # reduce using x^5 = x + 1
    k=len(tmp)-1
    while k>=5:
        c=tmp[k]
        if c:
            tmp[k]=0
            tmp[k-4]+=c  # x^k -> x^{k-4}
            tmp[k-5]+=c  # + x^{k-5}
        k-=1
    tmp += [0]*(5-len(tmp))
    return tmp[:5]

